    "year": 2010,
    "author": "@大排档诗人",
    "avatar": "📻",
    "timestamp": "10分钟前",
    "content": "放学在校门口小卖部买零食，大家都在热烈讨论让子弹飞，我揣着五毛钱买了一袋辣条和同桌分着吃。",
    "reply": "五毛钱的辣条配上全天下的大事，那是少年最朴实的英雄气概。",
