    "id": "seed-2010-03",
    "year": 2010,
    "author": "@二八大杠追风少年",
    "avatar": "🎸",
    "timestamp": "25分钟前",
    "content": "那年夏天坐着摇摇晃晃的绿皮慢车去省城，车站大喇叭里正播报着《让子弹飞》公映与姜文黑话风靡，车窗外全是金黄的麦田。",
    "reply": "车窗外飞速闪过的不仅是田野，更是那个正在大步向前的时代。",
